import{_ as l,o as a,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD 2020-08-19","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD 2020-08-19","date":"2020-08-19T00:00:00.000Z","updated":"2020-08-19T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","Crimson","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-19.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-19.md","lastUpdated":1780459816000}'),t={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-19.md"};function o(s,i,n,p,_,u){return a(),e("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>技术问题与解决方案</strong></p><ul><li>会议上讨论了Ceph存储系统在技术基础测试中遇到的问题，特别是与后台字段恢复相关的问题。</li><li>提出增加对缺少操作的支持，并解决对象不包含映射导致的运行时错误。</li><li>计划增强新添加操作的错误处理支持，以减少意外错误消息。</li></ul></li><li><p><strong>EIO处理案例</strong></p><ul><li>讨论了在代码中处理EIO的位置，特别是在CRC不匹配和对象存储返回EIO的情况下。</li><li>传统上，这些处理在经典OSD中通过rep_repair_primary函数完成，在Crimson中则需要在pg_backend中进行相应处理。</li></ul></li><li><p><strong>CRUSH算法的扩展</strong></p><ul><li>讨论了在FAST 2020会议上提出的一项关于CRUSH算法扩展的论文，该论文解决了非平凡集群扩展时数据迁移的问题。</li><li>计划继续讨论该论文，并将其链接分享给团队成员以供进一步研究。</li></ul></li><li><p><strong>代码实现与测试</strong></p><ul><li>完成了字符串键布局操作，并正在处理树节点实现。</li><li>解决了单元测试中发现的bug，并考虑如何改进基于PG日志的恢复。</li><li>强调了测试的重要性，特别是对于Crimson的稳定性和功能验证。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>需要对Crimson中的问题进行分类，并创建相应的bug报告。</li><li>强调了在病理运行中发现问题时，应及时创建bug报告。</li><li>计划继续优化代码，特别是错误处理和垃圾收集机制。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续推进对Crimson的测试和错误修复工作。</li><li>对发现的问题进行分类，并创建详细的bug报告。</li><li>继续研究和讨论CRUSH算法的扩展，以及其在Ceph中的应用。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续完善和增强Crimson的错误处理机制。</li><li>对Crimson中的问题进行分类，并创建详细的bug报告。</li><li>继续研究和讨论CRUSH算法的扩展，以及其在Ceph中的应用。</li><li>继续优化代码，特别是错误处理和垃圾收集机制。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议结束时，团队成员被鼓励继续关注和参与Crimson的开发和测试工作，并保持沟通和协作。</li></ul>',9)])])}const C=l(t,[["render",o]]);export{d as __pageData,C as default};
